# Retire a person from a date (none: the sheet's today). Validate before Load so a bad date is a 400,
# not masked by a 404; a person already retired is refused (400) and writes nothing.
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
  next: audit
# Record the change only once it is saved, so a refused change writes no audit line.
audit:
  class: net.officefloor.hq.app.person.AuditPersonRetired
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
-- A person may be retired from a date (none while active). A claim dated after it cannot be added or
-- edited to; claims dated on or before it still can. A retired person's claims keep counting.
ALTER TABLE person ADD COLUMN retired_from DATE;
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the retire body, refusing a from-date that is not a date. */
public class ValidateRetire {
    public void validate(@RequestBody RetireRequest request, Out<RetireInput> retireOut) throws InvalidPersonException {
        String from = request == null || request.from() == null ? "" : request.from().trim();
        if (from.isEmpty()) {
            retireOut.set(new RetireInput(null));
            return;
        }
        try {
            retireOut.set(new RetireInput(LocalDate.parse(from)));
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("The retired-from date must be a date (yyyy-mm-dd).");
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A validated retire body. The date is null when none was given (it defaults to the sheet's today). */
public record RetireInput(LocalDate from) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the given date (none: the sheet's today), refusing one already retired. */
public class RetirePerson {
    public void retire(@Val RetireInput input, @Val Person person, SheetRepository sheets) throws InvalidPersonException {
        if (person.getRetiredFrom() != null) {
            throw new InvalidPersonException(person.getName() + " is already retired.");
        }
        person.setRetiredFrom(input.from() != null ? input.from()
                : sheets.findById(person.getSheetId()).orElseThrow().getToday());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Records PERSON_RETIRED once the person is saved; the signed-in user arrives as X-User. */
public class AuditPersonRetired {
    public void audit(@Val Person person, @HttpHeaderParameter("X-User") String user, Audit audit) {
        audit.record("PERSON_RETIRED sheet=" + person.getSheetId() + " by=" + (user == null ? "" : user.trim())
                + " name=" + person.getName() + " from=" + person.getRetiredFrom());
    }
}
package net.officefloor.hq.app.person;

/** The audit line for a saved person: the event, sheet and user, then name and grade. */
public final class PersonAudit {
    private PersonAudit() {
    }

    public static String line(String event, Person person, String user) {
        return event + " sheet=" + person.getSheetId() + " by=" + (user == null ? "" : user.trim())
                + " name=" + person.getName() + " grade=" + person.getGrade();
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;

/** A person on a sheet, with a name and a grade (A, B or C); once retired, the date retired from. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "grade", nullable = false)
    private String grade;

    /** Raised by each save; an edit made against an older version is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    /** None while active; a claim dated after it is refused. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    protected Person() {
    }

    public Person(String sheetId) {
        this.sheetId = sheetId;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getGrade() {
        return grade;
    }

    public void setGrade(String grade) {
        this.grade = grade;
    }

    public long getVersion() {
        return version;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }
}
package net.officefloor.hq.app.person;

/** A person as shown; retiredFrom is yyyy-mm-dd, or null while not retired. */
public record PersonResponse(long id, String name, String grade, long version, String retiredFrom) {

    public static PersonResponse from(Person person) {
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(), person.getVersion(),
                person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString());
    }
}
package net.officefloor.hq.app.person;

/** The body of retiring a person: the date retired from (yyyy-mm-dd; empty means the sheet's today). */
public record RetireRequest(String from) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        personOut.set(repository.findByIdAndSheetId(personId, sheetId.trim())
                .orElseThrow(() -> new PersonNotFoundException("No such person on this sheet.")));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, PersonRepository repository) {
        repository.saveAndFlush(person); // flushed so the response carries the raised version
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person));
    }
}

